#[test]
fn tag_statuses_match() {
    assert_eq!(identify::tag_status("DRM protected"), Some(451));
    assert_eq!(identify::tag_status("upstream says 410 gone"), Some(410));
    assert_eq!(identify::tag_status("1404"), None);
    assert_eq!(identify::tag_status("no codes here"), None);
}

#[test]
fn ubit_recordings_parse() {
    for case in cases(&fixtures(), "ubitInfo") {
        let Some(plan) = case.get("plan").filter(|plan| !plan.is_null()) else {
            continue;
        };
        let stdout = part(plan, "stdout");
        let stderr = part(plan, "stderr");
        match identify::ubit_info_result(stdout.as_bytes(), stderr.as_bytes(), exit_code(plan)) {
            Ok(info) => same_json(
                &info,
                &case["out"],
                case["name"].as_str().unwrap_or_default(),
            ),
            Err(error) => same_json(
                &error_json(&error),
                &case["error"],
                case["name"].as_str().unwrap_or_default(),
            ),
        }
    }
}

/// The NDJSON state machine replays the same recorded chunks without a process.
#[test]
fn download_recordings_parse() {
    for case in cases(&fixtures(), "download") {
        if !case["cancelled"].is_null() {
            continue;
        }
        let Some(plan) = case.get("plan").filter(|plan| !plan.is_null()) else {
            continue;
        };
        if plan["hangAfterStdout"].as_u64().is_some() {
            continue;
        }
        let stall = Duration::from_millis(case["stallTimeout"].as_u64().unwrap_or(30_000));
        let mut state = DownloadState::new(stall);
        let mut progress: Vec<Value> = Vec::new();
        let stream = part(plan, "stdout");
        let mut parts: Vec<&str> = stream.split('\n').collect();
        if parts.last().is_some_and(|tail| tail.is_empty()) {
            parts.pop();
        }
        for line in parts {
            let LineOutcome {
                progress: reported,
                timeout: _,
            } = state.line(line, stall);
            if let Some(reported) = reported {
                progress.push(to_value(&reported));
            }
        }
        let name = case["name"].as_str().unwrap_or_default();
        match state.finish(exit_code(plan), part(plan, "stderr").as_bytes()) {
            Ok(downloaded) => same_json(&to_value(&downloaded), &case["out"], name),
            Err(error) => same_json(&error_json(&error), &case["error"], name),
        }
        same_json(&Value::Array(progress), &case["progress"], name);
    }
}

// --- request shapes -------------------------------------------------------------------------------------------

#[tokio::test]
async fn sends_match() {
    for case in cases(&fixtures(), "send") {
        let routes = case
            .get("routes")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_else(|| {
                case.get("route")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default()
            });
        let server = serve(Value::Array(routes)).await;
        let url = fill(&case["url"], &server.base);
        let timeout = case["timeoutMs"].as_u64().unwrap_or(10_000);
        let options = SendOptions {
            method: case["method"]
                .as_str()
                .unwrap_or("GET")
                .parse()
                .expect("method"),
            headers: vec![(
                "user-agent".to_owned(),
                case["userAgent"].as_str().unwrap_or("PearTube").to_owned(),
            )],
            timeout: Duration::from_millis(timeout),
            max_bytes: case["maxBytes"].as_u64(),
            redirects: 0,
        };
        let name = case["name"].as_str().unwrap_or_default();
        match art::send(url.as_str().expect("url"), options).await {
            Ok(response) => {
                let href = url::Url::parse(&response.url).expect("response url");
                let out = json!({
                    "status": response.status,
                    "urlPath": format!("{}{}", href.path(), href.query().map(|q| format!("?{q}")).unwrap_or_default()),
                    "contentType": response.header("content-type"),
                    "body": response.body,
                });
                same_json(&out, &case["out"], name);
            }
            Err(error) => same_json(
                &json!({
                    "message": error.message(),
                    "status": null,
                    "code": null,
                }),
                &case["error"],
                name,
            ),
        }
        same_json(
            &seen_json(&server.seen.lock().expect("seen")),
            &case["requests"],
            name,
        );
    }
}

/// The app's own byte cap: `request.destroy(err)` there surfaces as an uncaught socket error, so it is only
/// recorded here rather than in the JS reference.
#[tokio::test]
async fn a_reply_over_max_bytes_is_refused() {
    let server =
        serve(json!([{ "path": "/big", "status": 200, "body": "0123456789abcdefghij" }])).await;
    let error = art::send(
        &format!("{}/big", server.base),
        SendOptions {
            max_bytes: Some(10),
            ..Default::default()
        },
    )
    .await
    .expect_err("over the cap");
    assert_eq!(error.message(), "Reply exceeded 10 bytes");
}

#[tokio::test]
async fn cinemeta_searches_match() {
    for case in cases(&fixtures(), "cinemeta") {
        let requests = case["requests"].as_array().cloned().unwrap_or_default();
        let routes: Vec<Value> = requests
            .iter()
            .map(|request| {
                json!({
                    "path": request["path"],
                    "status": case["status"],
                    "headers": { "content-type": "application/json" },
                    "body": case["body"],
                })
            })
            .collect();
        let server = serve(Value::Array(routes)).await;
        let base = if case["hasBase"].as_bool().unwrap_or(true) {
            server.base.clone()
        } else {
            String::new()
        };
        let title = case["title"].as_str().unwrap_or_default();
        let year = case["year"].as_u64().map(|year| year as u32);
        let season = case["season"].as_u64().map(|season| season as u32);
        let found = identify::cinemeta_search(&base, title, year, season)
            .await
            .expect("search");
        same_json(
            &Value::Array(found.iter().map(to_value).collect()),
            &case["out"],
            case["name"].as_str().unwrap_or_default(),
        );
        same_json(
            &seen_json(&server.seen.lock().expect("seen")),
            &case["requests"],
            case["name"].as_str().unwrap_or_default(),
        );
    }
}

#[tokio::test]
async fn metadata_lookups_match() {
    art::clear_meta_cache();
    for case in cases(&fixtures(), "meta") {
        let imdb = case["imdb"].as_str().expect("imdb");
        let name = case["name"].as_str().unwrap_or_default();
        for step in case["steps"].as_array().expect("steps") {
            let server = serve(step["routes"].clone()).await;
            let actual = json!({
                "meta": art::meta_for(&server.base, imdb).await,
                "poster": art::poster_url(&server.base, imdb).await,
                "backdrop": art::backdrop_url(&server.base, imdb).await,
                "requests": seen_json(&server.seen.lock().expect("seen")),
            });
            let expected = json!({
                "meta": step["meta"],
                "poster": step["poster"],
                "backdrop": step["backdrop"],
                "requests": step["requests"],
            });
            same_json(&actual, &expected, name);
        }
    }
}

// --- the subprocess and the whole identification --------------------------------------------------------------

#[tokio::test]
async fn ubit_info_calls_match() {
    for case in cases(&fixtures(), "ubitInfo") {
        let plan = case.get("plan").cloned().unwrap_or(Value::Null);
        let (program, fake) = if plan.is_null() {
            ("/nonexistent/ubit".to_owned(), None)
        } else {
            let fake = FakeUbit::new(&plan);
            (fake.program(), Some(fake))
        };
        let url = case["url"].as_str().expect("url");
        let name = case["name"].as_str().unwrap_or_default();
        let config_dir = case["configDir"].as_str().unwrap_or_default();
        let info =
            identify::ubit_info(&program, url, config_dir, Duration::from_millis(45_000)).await;
        match info {
            Ok(info) => same_json(&info, &case["out"], name),
            Err(error) => same_json(&error_json(&error), &case["error"], name),
        }
        if let Some(fake) = &fake {
            same_json(&fake.observed("", ""), &case["observed"], name);
        }
    }
}

#[tokio::test]
async fn probes_match() {
    for case in cases(&fixtures(), "probe") {
        let server = serve(Value::Array(
            case["headerRoutes"].as_array().cloned().unwrap_or_default(),
        ))
        .await;
        let plan = case["plan"].clone();
        let fake = (!plan.is_null()).then(|| FakeUbit::new(&plan));
        let url = fill(&case["url"], &server.base);
        let url = url.as_str().expect("url");
        let options = ProbeOptions {
            ubit: fake
                .as_ref()
                .map_or_else(|| "/nonexistent/ubit".to_owned(), FakeUbit::program),
            ..Default::default()
        };
        let name = case["name"].as_str().unwrap_or_default();
        match identify::probe(url, &options).await {
            Ok(link) => {
                let mut out = to_value(&link);
                if let Some(page_id) = link.page_id() {
                    out["pageId"] = Value::String(page_id.to_owned());
                }
                same_json(&out, &fill(&case["out"], &server.base), name);
            }
            Err(error) => same_json(
                &error_json(&error),
                &fill(&case["error"], &server.base),
                name,
            ),
        }
        same_json(
            &seen_json(&server.seen.lock().expect("seen")),
            &case["requests"],
            name,
        );
        if let Some(fake) = &fake {
            same_json(&fake.observed(&server.base, ""), &case["observed"], name);
        }
    }
}

#[tokio::test]
async fn identify_matches() {
    for case in cases(&fixtures(), "identify") {
        let server = serve(Value::Array(
            case["routes"].as_array().cloned().unwrap_or_default(),
        ))
        .await;
        let plan = case["plan"].clone();
        let fake = (!plan.is_null()).then(|| FakeUbit::new(&plan));
        let url = fill(&case["url"], &server.base);
        let options = IdentifyOptions {
            cinemeta_url: server.base.clone(),
            config_dir: String::new(),
            ubit: fake
                .as_ref()
                .map_or_else(|| "/nonexistent/ubit".to_owned(), FakeUbit::program),
        };
        let name = case["name"].as_str().unwrap_or_default();
        let found = identify::identify(url.as_str().expect("url"), &options)
            .await
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        let mut out = to_value(&found);
        let mut expected = fill(&case["out"], &server.base);
        if !case["stableId"].as_bool().unwrap_or(true) {
            // The clip id hashes the link itself, and the port differs between the app's run and this one.
            assert!(out["plain"]["id"].is_string() && expected["plain"]["id"].is_string());
            out["plain"]["id"] = Value::Null;
            expected["plain"]["id"] = Value::Null;
        }
        same_json(&out, &expected, name);
        same_json(
            &seen_json(&server.seen.lock().expect("seen")),
            &case["requests"],
            name,
        );
    }
}

#[tokio::test]
async fn downloads_match() {
    for case in cases(&fixtures(), "download") {
        let plan = case["plan"].clone();
        let fake = (!plan.is_null()).then(|| FakeUbit::new(&plan));
        let out_dir = std::env::temp_dir().join(format!(
            "peartube-out-{}-{:x}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        ));
        fs::create_dir_all(&out_dir).expect("out dir");
        let out_dir_text = out_dir.to_string_lossy().into_owned();
        let progress: Arc<Mutex<Vec<Value>>> = Arc::new(Mutex::new(Vec::new()));
        let controller = Controller::new();
        let cancellation = case["cancelled"].as_str();
        if cancellation == Some("before") {
            controller.abort();
        }
        let progress_sink = progress.clone();
        let controller_for_progress = controller.clone();
        let cancel_on_progress = cancellation == Some("progress");
        let options = DownloadOptions {
            config_dir: case["configDir"].as_str().unwrap_or_default().to_owned(),
            stall_timeout: Duration::from_millis(case["stallTimeout"].as_u64().unwrap_or(30_000)),
            ubit: fake
                .as_ref()
                .map_or_else(|| "/nonexistent/ubit".to_owned(), FakeUbit::program),
            controller: cancellation.map(|_| controller.clone()),
            on_progress: Some(Box::new(move |reported: DownloadProgress| {
                progress_sink
                    .lock()
                    .expect("progress")
                    .push(to_value(&reported));
                if cancel_on_progress {
                    controller_for_progress.abort();
                }
            })),
        };
        let url = case["url"].as_str().expect("url");
        let name = case["name"].as_str().unwrap_or_default();
        let result = identify::download_page(url, &out_dir_text, options).await;
        match result {
            Ok(downloaded) => same_json(&to_value(&downloaded), &case["out"], name),
            Err(error) => same_json(&error_json(&error), &case["error"], name),
        }
        same_json(
            &Value::Array(progress.lock().expect("progress").clone()),
            &case["progress"],
            name,
        );
        if let Some(fake) = &fake {
            same_json(&fake.observed(url, &out_dir_text), &case["observed"], name);
        }
        let _ = fs::remove_dir_all(&out_dir);
    }
}
